import React from 'react';

import { IQuestionDir, IQuestionDirWithAnswer } from '@apps/Interview/@types/interview.types';
import PohInput from '@ui-kit/Input';
import PohList from '@ui-kit/List';
import PohSelect from '@ui-kit/Select';

interface IQuestionDirProps {
  data: IQuestionDir;
  result?: IQuestionDirWithAnswer;
  disabled?: boolean;
}

const QuestionDir: React.FC<IQuestionDirProps> = ({ data, disabled, result }) => {
  return (
    <div>
      <PohList
        data={[].map((x) => {
          return {
            key: 1,
            children: <PohSelect label={x} disabled={disabled} />,
          };
        })}
      />
      <PohInput
        defaultValue={result?.customValue ?? ''}
        disabled={disabled}
        required
        placeholder={'Свой вариант'}
      />
      <div>
        <small>{data.text}</small>
      </div>
    </div>
  );
};

export default QuestionDir;
